def transform_bbox(I,bg,fun):
 O=I.copy();mask=(I!=0)&(I!=bg);O[mask]=0
 p=np.argwhere(mask);r0,c0=p.min(0);r1,c1=p.max(0)
 A=I[r0:r1+1,c0:c1+1];X=fun(A)
 O[r0:r1+1,c0:c1+1][(X!=0)&(X!=bg)]=X[(X!=0)&(X!=bg)]
 return O
